solution.Birthdays.java:
import java.time.LocalDate;
import java.time.Period;
import java.time.temporal.ChronoUnit;

public class Birthdays {
    public static int age(LocalDate born, LocalDate today) {
        return Period.between(born, today).getYears();
    }

    public static long daysUntilNextBirthday(LocalDate born, LocalDate today) {
        LocalDate next = born.withYear(today.getYear());          // withYear clamps 29 Feb to 28 Feb
        if (next.isBefore(today)) next = born.withYear(today.getYear() + 1);
        return ChronoUnit.DAYS.between(today, next);
    }
}

unitTests:
test("age", () -> {
    checkEq(Birthdays.age(LocalDate.of(1990, 11, 21), LocalDate.of(2026, 11, 20)), 35);
    checkEq(Birthdays.age(LocalDate.of(1990, 11, 20), LocalDate.of(2026, 11, 20)), 36);
});

test("next birthday", () -> {
    checkEq(Birthdays.daysUntilNextBirthday(LocalDate.of(1990, 11, 20), LocalDate.of(2026, 11, 20)), 0L);
    checkEq(Birthdays.daysUntilNextBirthday(LocalDate.of(1990, 11, 21), LocalDate.of(2026, 11, 20)), 1L);
    checkEq(Birthdays.daysUntilNextBirthday(LocalDate.of(1990, 1, 1), LocalDate.of(2026, 12, 31)), 1L);
    checkEq(Birthdays.daysUntilNextBirthday(LocalDate.of(2000, 2, 29), LocalDate.of(2026, 2, 1)), 27L);
    checkEq(Birthdays.daysUntilNextBirthday(LocalDate.of(2000, 2, 29), LocalDate.of(2027, 3, 1)), 365L);
});

